    @Transactional
    public Xzj27 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
                                          boolean isWarehouseStorage, Xbf54RequestDto paymentRequest) {
        try {

            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);


            Xrd81 buyer = userQueryService.findByEmail(buyerEmail);


            Xzz58 saleBid = getSaleBidAndValidate(saleBidId);
            Xgg74 sale = saleBid.getSale();


            Xdg64 order = orderCommandService.createInstantOrder(
                    buyer,
                    saleBid,
                    addressId,
                    isWarehouseStorage,
                    paymentRequest
            );


            Xzj27 orderBid = createInstantOrderBid(order, saleBid, sale);

            return orderBid;
        } catch (Exception e) {
            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
            return null;
        }
    }




    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, Xbf54RequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new Xxd47Exception("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new Xkt44Exception("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new Xnb95Exception("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new Xtj87Exception("결제 정보가 없습니다.");
        }
    }



